import { assert, assertEquals, assertThrows } from "https://deno.land/std@0.224.0/assert/mod.ts";
import { Registry, createHeadlessHost } from "./petri-commands.js";
import {
    ENGINE_OVERRIDES, EXCLUDED, GOAL_DIRECT_TOOLS, GOAL_MANIFEST_VERSION, GOAL_VIEWS,
    buildGoalManifest, buildManifest, decodeGoalCall, indexHelp,
} from "./petri-tools.js";

// The goal toolset (docs/design/agent-first-analysis.md 4.2): public/llm-goal-tools.json
// is generated by scripts/gen-llm-tools.mjs; the first test is the drift gate, as
// petri-chat_test.ts has for llm-tools.json.

const goalManifest = JSON.parse(await Deno.readTextFile(new URL("./llm-goal-tools.json", import.meta.url)));
const fullManifest = JSON.parse(await Deno.readTextFile(new URL("./llm-tools.json", import.meta.url)));
const catalog = JSON.parse(await Deno.readTextFile(new URL("./goals.json", import.meta.url)));
const availableGoals: string[] = catalog.goals.filter((g: any) => g.available !== false).map((g: any) => g.id);

const specs = () => {
    const host: any = createHeadlessHost();
    host.capabilities = new Set(["view"]);
    return new (Registry as any)(host).list();
};

const PSEUDO = ["run_goal", "ask_user", "command_schema", "run_command", "open_view"];
const decl = (t: any) => JSON.stringify({ name: t.name, description: t.description, parameters: t.parameters });

Deno.test("goal tools: public/llm-goal-tools.json is what the registry and goals.json generate (run scripts/gen-llm-tools.mjs)", () => {
    assertEquals(buildGoalManifest(specs(), catalog), goalManifest);
    assertEquals(goalManifest.version, GOAL_MANIFEST_VERSION);
});

Deno.test("goal tools: run_goal's enum is exactly the available goals of goals.json, so a typo cannot reach the server", () => {
    const run = goalManifest.tools.find((t: any) => t.name === "run_goal");
    assertEquals(run.parameters.properties.goal_id.enum, availableGoals);
    assert(!availableGoals.includes("data_match"), "an unavailable goal is not offered");
    assertEquals(run.parameters.required, ["goal_id"]);
    assertEquals(run.json_args, ["inputs"]);
    assertEquals(run.parameters.properties.engine_override.enum, ENGINE_OVERRIDES);
    assertEquals(goalManifest.tools.find((t: any) => t.name === "open_view").parameters.properties.view.enum, GOAL_VIEWS);
});

Deno.test("goal tools: fewer than 30 tools, unique Gemini-safe names, Gemini's schema subset", () => {
    assert(goalManifest.tools.length < 30, `${goalManifest.tools.length} tools`);
    assertEquals(goalManifest.tools.length, PSEUDO.length + GOAL_DIRECT_TOOLS.length);
    const names = goalManifest.tools.map((t: any) => t.name);
    assertEquals(new Set(names).size, names.length, "names are unique");
    for (const n of names) assert(/^[a-zA-Z_][a-zA-Z0-9_]{0,63}$/.test(n), n);
    const walk = (s: any, path: string) => {
        assert(!Array.isArray(s.type), `${path}: union type`);
        assert(!("additionalProperties" in s), `${path}: additionalProperties`);
        assert(!("minItems" in s) && !("maxItems" in s), `${path}: array bounds are enforced by the server, not declared`);
        if (s.type === "object") for (const [k, v] of Object.entries(s.properties || {})) walk(v, `${path}.${k}`);
        if (s.items) walk(s.items, `${path}[]`);
    };
    for (const t of goalManifest.tools) {
        assert(t.description && t.description.length <= 1000, t.name);
        if (t.parameters) {
            walk(t.parameters, t.name);
            for (const r of t.parameters.required || []) assert(r in t.parameters.properties, `${t.name}: required ${r} is not a property`);
        }
        for (const k of t.json_args || []) assertEquals(t.parameters.properties[k].type, "string", `${t.name}.${k}: JSON arguments travel as strings`);
    }
});

Deno.test("goal tools: the pseudo-tools carry ask: true and no command; every other tool is a registry command", () => {
    const registry = new Set(specs().map((s: any) => s.id));
    const byName = new Map(goalManifest.tools.map((t: any) => [t.name, t]));
    for (const n of PSEUDO) {
        const t: any = byName.get(n);
        assert(t, n);
        assertEquals(t.ask, true, n);
        assert(!("command" in t), `${n} has no command`);
    }
    const rest = goalManifest.tools.filter((t: any) => !PSEUDO.includes(t.name));
    assertEquals(rest.map((t: any) => t.command), GOAL_DIRECT_TOOLS.map((d) => d.command));
    for (const t of rest) {
        assert(!t.ask, t.name);
        assert(registry.has(t.command), `${t.name}: ${t.command} is not a registry command`);
        assert(!EXCLUDED.has(t.command), `${t.name}: excluded from the chat`);
        // exactly the declaration the full manifest has: one description of a command, not two
        assertEquals(t, fullManifest.tools.find((f: any) => f.command === t.command));
    }
    for (const d of GOAL_DIRECT_TOOLS) assert(d.why.length > 20, `${d.command}: say why it is declared`);
    assertEquals(new Set(GOAL_DIRECT_TOOLS.map((d) => d.command)).size, GOAL_DIRECT_TOOLS.length);
});

Deno.test("goal tools: the edit set covers what the build flow does, and read/edit commands stay in the sandbox kinds the chat knows", () => {
    const commands = GOAL_DIRECT_TOOLS.map((d) => d.command);
    for (const c of ["net.info", "net.add_place", "net.add_transition", "net.add_arc", "net.set_place", "edit.delete", "edit.undo", "sim.set_rate", "analysis.check", "view.highlight", "view.fit"]) {
        assert(commands.includes(c), `${c} is in the set`);
    }
    // the scripted interview of petri-refine_test.ts needs these; each is either declared or in the index (behind run_command)
    const reachable = new Set([...commands, ...goalManifest.command_index.map((e: any) => e.id)]);
    for (const c of ["compose.fuse", "net.set_goals", "analysis.defects", "sim.recommend", "compose.components"]) assert(reachable.has(c), c);
});

Deno.test("goal tools: command_index is every other command the full manifest declares, once, with one line of help", () => {
    const direct = new Set(GOAL_DIRECT_TOOLS.map((d) => d.command));
    const ids = goalManifest.command_index.map((e: any) => e.id);
    assertEquals(new Set(ids).size, ids.length, "ids are unique");
    const expected = fullManifest.tools.map((t: any) => t.command).filter((c: string) => !direct.has(c));
    assertEquals(ids, expected);
    for (const e of goalManifest.command_index) {
        assert(e.help && !e.help.includes("\n") && e.help.length <= 60, `${e.id}: ${JSON.stringify(e.help)}`);
        assert(!EXCLUDED.has(e.id));
    }
    // commands that write the person's own library or store are not reachable at all
    for (const id of ids) assert(!/^(model\.save|model\.delete|store\.put|store\.license|file\.save)$/.test(id), id);
});

Deno.test("goal tools: indexHelp keeps the first sentence, cuts at a word and never inside a parenthesis", () => {
    assertEquals(indexHelp("Frame the whole net."), "Frame the whole net");
    assertEquals(indexHelp("Undo the last edit. More text that is dropped."), "Undo the last edit");
    assertEquals(indexHelp(""), "");
    const long = indexHelp("The document as pflow.xyz JSON-LD (unbounded capacities as null), exported with every field.");
    assert(long.endsWith("…") && long.length <= 60 && !long.includes("(unbounded"), long);
    const cut = indexHelp("Sweep one transition's rate and record each place's value at t_end (the editor's steady-state reading).");
    assert(cut.endsWith("…") && !/\b(a|the|of|and)…$/.test(cut), cut);
    assert(indexHelp("x ".repeat(80)).length <= 58);
});

Deno.test("goal tools: a goal call decodes with its JSON argument parsed; a command call decodes as the registry command", () => {
    const g: any = decodeGoalCall(goalManifest, { name: "run_goal", args: { goal_id: "knob", inputs: '{"observable": "I"}' } });
    assertEquals([g.pseudo, g.name, g.args], [true, "run_goal", { goal_id: "knob", inputs: { observable: "I" } }]);
    // a blank argument is no argument
    assertEquals((decodeGoalCall(goalManifest, { name: "run_goal", args: { goal_id: "stuck", inputs: "  " } }) as any).args, { goal_id: "stuck" });
    assertEquals((decodeGoalCall(goalManifest, { name: "run_command", args: { id: "sim.ode", args: '{"t_end": 5}', engine_override: "ode" } }) as any).args,
        { id: "sim.ode", args: { t_end: 5 }, engine_override: "ode" });
    assertEquals((decodeGoalCall(goalManifest, { name: "ask_user", args: { question: "Which?", options: ["a", "b"] } }) as any).pseudo, true);
    assertThrows(() => decodeGoalCall(goalManifest, { name: "run_goal", args: { goal_id: "knob", inputs: "{oops" } }), Error, "not valid JSON");
    assertThrows(() => decodeGoalCall(goalManifest, { name: "sim_ode", args: {} }), Error, "unknown tool");
    const e: any = decodeGoalCall(goalManifest, { name: "sim_set_rate", args: { id: "t", rate: 2 } });
    assertEquals([e.pseudo, e.command, e.args], [false, "sim.set_rate", { id: "t", rate: 2 }]);
    const v: any = decodeGoalCall(goalManifest, { name: "view_highlight", args: { nodes: ["a"], weights: '{"a": 2}' } });
    assertEquals(v.args.weights, { a: 2 });
});

Deno.test("goal tools: the declarations are a fraction of the full manifest (measurement; bytes/4 is the rough token count)", () => {
    const all = fullManifest.tools.map(decl).join("").length;
    const goals = goalManifest.tools.map(decl).join("").length;
    const index = goalManifest.command_index.map((e: any) => `${e.id}: ${e.help}`).join("\n").length;
    const tok = (b: number) => `${b} B ~ ${Math.round(b / 4)} tokens`;
    console.log(`llm-tools.json: ${fullManifest.tools.length} tools, declarations ${tok(all)} (file ${tok(JSON.stringify(fullManifest).length)})`);
    console.log(`llm-goal-tools.json: ${goalManifest.tools.length} tools, declarations ${tok(goals)}, command index (${goalManifest.command_index.length} lines) ${tok(index)}, together ${tok(goals + index)}`);
    assert(goals * 5 < all, "the goal declarations are under a fifth of the full manifest's");
    assert((goals + index) * 3 < all, "declarations plus the index are under a third of it");
});
